SELECT *, NTILE(3) OVER (PARTITION BY promo_code, channel ORDER BY discount_pct, id) AS discount_pct_bucket, AVG(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS discount_pct_avg_5_prior, FIRST_VALUE(channel, TRUE) OVER w_hist AS first_known_channel FROM promotions WINDOW w_hist AS (PARTITION BY promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
